"use client"

import * as React from "react"
import { toast } from "sonner"

import {
  Alert,
  AlertAction,
  AlertDescription,
  AlertTitle,
} from "@/components/ui/alert"
import { Button } from "@/components/ui/button"
import { Card, CardContent } from "@/components/ui/card"
import { Field, FieldGroup, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import {
  Item,
  ItemActions,
  ItemContent,
  ItemDescription,
  ItemTitle,
} from "@/components/ui/item"
import { Textarea } from "@/components/ui/textarea"
import { EditorHeader } from "@/components/mockups/config-versioning/editor-header"
import { HistoryDrawer } from "@/components/mockups/config-versioning/history-drawer"
import { BackToNewestIcon } from "@/components/mockups/config-versioning/icons"
import { SaveReview } from "@/components/mockups/config-versioning/save-review"
import {
  type CaseId,
  RIVAL,
  type Subject,
  type Version,
} from "@/lib/mockups/config-versioning-data"

/**
 * The editor for anything versioned — a scenario's Scenario tab, or the
 * global prompt — cut to what DES-202 changes.
 *
 *  - Save makes a version. Live or not, the save review says what the save
 *    does to callers (save-review.tsx).
 *  - On a live item with saves ahead of the marker, one row under the header
 *    says which versions are not live and offers Review and publish. It is
 *    the ticket's draft indicator, unpublished state and publish action in
 *    one place, and it is absent when there is nothing to publish.
 *  - History (history-drawer.tsx) is where publishing, rolling back and
 *    "edit from here" happen, with the comparison on screen.
 *  - Edit from here opens an earlier version as the starting point, says so
 *    above the fields, and saves as a new version on top (PRD).
 */
export function VersionedEditor({
  initial,
  caseId,
}: {
  initial: Subject
  caseId: CaseId
}) {
  const [subject, setSubject] = React.useState(initial)
  const [base, setBase] = React.useState(initial.versions[0].n)
  const [draft, setDraft] = React.useState(initial.versions[0].body)
  const [reviewing, setReviewing] = React.useState(false)
  const [history, setHistory] = React.useState<{
    n: number
    against: number | null
  } | null>(null)
  const [rival, setRival] = React.useState<Version | null>(null)

  const canEdit = caseId !== "view-only"
  const newest = subject.versions[0]
  const baseVersion =
    subject.versions.find((version) => version.n === base) ?? newest
  const editingFrom = base !== newest.n && !rival
  const changes = subject.fields.filter(
    (field) => draft[field.id] !== newest.body[field.id],
  ).length
  const live = subject.marker !== null
  const ahead = live
    ? subject.versions.filter((v) => v.n > subject.marker!)
    : []

  /* A summary for a fresh save arrives a moment later (PRD: generation never
     blocks the save). In the pending case it never does. */
  React.useEffect(() => {
    if (caseId === "summary-pending") return
    if (newest.summary !== null) return
    const timer = setTimeout(
      () =>
        setSubject((current) => ({
          ...current,
          versions: current.versions.map((version) =>
            version.summary === null
              ? { ...version, summary: summarise(current, version) }
              : version,
          ),
        })),
      2500,
    )
    return () => clearTimeout(timer)
  }, [caseId, newest.summary])

  function openReview() {
    /* The conflict case: someone else's save lands after this page opened. */
    if (caseId === "conflict" && !rival) {
      const theirs: Version = {
        ...RIVAL,
        n: newest.n + 1,
        editedFrom: newest.n,
        body: {
          ...newest.body,
          [subject.fields[0].id]:
            `${newest.body[subject.fields[0].id]} I'm calling from the Olaya branch.`,
        },
      }
      setRival(theirs)
      setSubject((current) => ({
        ...current,
        versions: [theirs, ...current.versions],
      }))
    }
    setReviewing(true)
  }

  function save() {
    const n = subject.versions[0].n + 1
    const made: Version = {
      n,
      author: "You",
      mine: true,
      at: "Just now",
      editedFrom: base,
      summary: null,
      everLive: false,
      body: draft,
    }
    setSubject((current) => ({
      ...current,
      versions: [made, ...current.versions],
    }))
    setBase(n)
    setRival(null)
    setReviewing(false)
    toast.success(`Saved as v${n}`, {
      description: live
        ? `Callers still hear v${subject.marker}.`
        : "It runs from the next call.",
    })
  }

  function discard() {
    const before = { draft, base }
    setDraft(newest.body)
    setBase(newest.n)
    toast("Changes discarded", {
      action: {
        label: "Undo",
        onClick: () => {
          setDraft(before.draft)
          setBase(before.base)
        },
      },
    })
  }

  async function publish(n: number): Promise<boolean> {
    await new Promise((resolve) => setTimeout(resolve, 900))
    if (caseId === "publish-fails") return false
    const before = { marker: subject.marker, published: subject.published }
    setSubject((current) => ({
      ...current,
      marker: n,
      published: { by: "You", at: "Just now" },
      versions: current.versions.map((version) =>
        version.n === n ? { ...version, everLive: true } : version,
      ),
    }))
    setHistory(null)
    toast.success(`v${n} is live`, {
      description:
        before.marker !== null && n < before.marker
          ? `Rolled back from v${before.marker}. No version was made.`
          : "Callers hear it from the next call.",
      action: {
        label: "Undo",
        onClick: () =>
          setSubject((current) => ({
            ...current,
            marker: before.marker,
            published: before.published,
          })),
      },
    })
    return true
  }

  function editFrom(n: number) {
    const version = subject.versions.find((item) => item.n === n)
    if (!version) return
    setBase(n)
    setDraft(version.body)
    setHistory(null)
  }

  function toggleLive(on: boolean) {
    const before = { marker: subject.marker, published: subject.published }
    setSubject((current) => ({
      ...current,
      marker: on ? current.versions[0].n : null,
      published: on ? { by: "You", at: "Just now" } : null,
      versions: on
        ? current.versions.map((version, index) =>
            index === 0 ? { ...version, everLive: true } : version,
          )
        : current.versions,
    }))
    toast(
      on ? `${subject.name} is live` : `${subject.name} is no longer live`,
      {
        description: on
          ? `v${newest.n} is the live version. Saves wait for a publish.`
          : `v${newest.n} runs from the next call. Saves apply straight away.`,
        action: {
          label: "Undo",
          onClick: () =>
            setSubject((current) => ({
              ...current,
              marker: before.marker,
              published: before.published,
            })),
        },
      },
    )
  }

  return (
    <main className="mx-auto flex w-full max-w-3xl flex-col gap-6 p-8 pb-28">
      <EditorHeader
        base={base}
        canEdit={canEdit}
        onOpenHistory={() => setHistory({ n: newest.n, against: null })}
        onToggleLive={toggleLive}
        subject={subject}
      />

      {ahead.length > 0 ? (
        <Item variant="outline">
          <ItemContent>
            <ItemTitle className="tabular-nums">
              {ahead.length === 1
                ? `v${ahead[0].n} isn’t live yet`
                : `v${ahead[ahead.length - 1].n} to v${ahead[0].n} aren’t live yet`}
            </ItemTitle>
            <ItemDescription className="tabular-nums">
              Callers hear v{subject.marker}.
            </ItemDescription>
          </ItemContent>
          <ItemActions>
            <Button
              onClick={() =>
                setHistory({ n: newest.n, against: subject.marker })
              }
            >
              Review and publish
            </Button>
          </ItemActions>
        </Item>
      ) : null}

      {editingFrom ? (
        <Alert>
          <AlertTitle className="tabular-nums">Editing from v{base}</AlertTitle>
          <AlertDescription className="tabular-nums">
            {baseVersion.author}, {baseVersion.at}. Saving makes v{newest.n + 1}{" "}
            with this content; v{newest.n} stays in history.
          </AlertDescription>
          <AlertAction>
            <Button onClick={discard} size="sm" variant="outline">
              <BackToNewestIcon />
              Back to v{newest.n}
            </Button>
          </AlertAction>
        </Alert>
      ) : null}

      <FieldGroup>
        {subject.fields.map((field) => (
          <Field key={field.id}>
            <FieldLabel htmlFor={field.id}>{field.label}</FieldLabel>
            {field.multiline ? (
              <Textarea
                dir="auto"
                disabled={!canEdit}
                id={field.id}
                onChange={(event) =>
                  setDraft((current) => ({
                    ...current,
                    [field.id]: event.target.value,
                  }))
                }
                rows={6}
                value={draft[field.id]}
              />
            ) : (
              <Input
                dir="auto"
                disabled={!canEdit}
                id={field.id}
                onChange={(event) =>
                  setDraft((current) => ({
                    ...current,
                    [field.id]: event.target.value,
                  }))
                }
                value={draft[field.id]}
              />
            )}
          </Field>
        ))}
      </FieldGroup>

      {changes > 0 ? (
        <Card className="sticky bottom-4" size="sm">
          <CardContent className="flex items-center gap-3">
            <span className="text-sm tabular-nums">
              {changes === 1 ? "1 change" : `${changes} changes`}
            </span>
            <div className="ms-auto flex items-center gap-2">
              <Button onClick={discard} variant="ghost">
                Discard
              </Button>
              <Button onClick={openReview}>Review and save</Button>
            </div>
          </CardContent>
        </Card>
      ) : null}

      <SaveReview
        base={base}
        draft={draft}
        onOpenChange={setReviewing}
        onSave={save}
        open={reviewing}
        rival={rival}
        subject={subject}
      />

      <HistoryDrawer
        canEdit={canEdit}
        caseId={caseId}
        editing={base}
        initial={history ?? { n: newest.n, against: null }}
        onEditFrom={editFrom}
        onOpenChange={(open) => {
          if (!open) setHistory(null)
        }}
        onPublish={publish}
        open={history !== null}
        subject={
          caseId === "view-only"
            ? {
                ...subject,
                versions: subject.versions.map((v) => ({ ...v, mine: false })),
              }
            : subject
        }
      />
    </main>
  )
}

/** A stand-in for the generated summary: which parts the save touched. */
function summarise(subject: Subject, version: Version) {
  const parent = subject.versions.find((item) => item.n === version.editedFrom)
  const touched = subject.fields
    .filter(
      (field) => parent && parent.body[field.id] !== version.body[field.id],
    )
    .map((field) => field.label)
  return touched.length
    ? `${touched.join(" and ")}: edited${version.editedFrom ? ` from v${version.editedFrom}` : ""}.`
    : `Same content as v${version.editedFrom}.`
}

"use client"

import * as React from "react"
import { Cancel01Icon, PlusSignIcon } from "@hugeicons/core-free-icons"
import type { DateRange } from "react-day-picker"

import { Button } from "@/components/ui/button"
import { ButtonGroup } from "@/components/ui/button-group"
import { Calendar } from "@/components/ui/calendar"
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command"
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Field, FieldLabel } from "@/components/ui/field"
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
  InputGroupText,
} from "@/components/ui/input-group"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import { Separator } from "@/components/ui/separator"
import { icon } from "@/components/shared/icon"

const AddIcon = icon(PlusSignIcon, "AddIcon")
const ClearIcon = icon(Cancel01Icon, "ClearIcon")

export type { DateRange }
export type FilterOption = { value: string; label: string }
export type Range = { min?: number; max?: number }

/**
 * Filters as a row of chips under the search.
 *
 * A filter that is not set is one small chip naming its field — "+ Language" —
 * so ten of them cost a line, not a toolbar. Opening one gives its control the
 * room it needs (a checklist, a calendar) in a popover. Once set, the chip
 * reads its value and grows an × to clear it. Past two set filters the row
 * ends in Clear all.
 *
 * Show the three or four filters people reach for as chips; put the rest
 * behind AddFilter, which turns a chosen field into a chip of its own.
 */
export function FilterBar({
  children,
  activeCount = 0,
  onClearAll,
}: {
  children: React.ReactNode
  /** How many filters are set. Clear all appears at two. */
  activeCount?: number
  onClearAll?: () => void
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      {children}
      {activeCount >= 2 ? (
        <Button variant="ghost" size="xs" onClick={onClearAll}>
          Clear all
        </Button>
      ) : null}
    </div>
  )
}

/**
 * The chip itself: "+ Field" when empty, "Field: value" and an × once set.
 * One tree for both states: swapping the button for a group once a value is
 * set would remount the trigger, and the open list would close on the first
 * tick.
 */
function Chip({
  field,
  summary,
  onClear,
  trigger,
}: {
  field: string
  /** What the filter is set to, or null when it is not set. */
  summary: string | null
  onClear: () => void
  trigger: (button: React.ReactElement) => React.ReactNode
}) {
  return (
    <ButtonGroup>
      {trigger(
        <Button variant="outline" size="xs">
          {summary ? (
            <>
              {field}: <span className="font-semibold">{summary}</span>
            </>
          ) : (
            <>
              <AddIcon />
              {field}
            </>
          )}
        </Button>,
      )}
      {summary ? (
        <Button
          variant="outline"
          size="icon-xs"
          aria-label={`Clear ${field}`}
          onClick={onClear}
        >
          <ClearIcon />
        </Button>
      ) : null}
    </ButtonGroup>
  )
}

/* ---------------------------------------------------------------- summaries */

/**
 * What a many-value filter reads once set: the value, two values when both
 * fit, and past that the first value and how many more — "Completed +2".
 * A bare count ("Status: 3") makes you open the chip to learn anything.
 */
function manySummary(options: FilterOption[], value: string[]) {
  if (!value.length) return null
  const labels = value.map(
    (item) => options.find((option) => option.value === item)?.label ?? item,
  )
  if (labels.length === 1) return labels[0]
  if (labels.length === 2 && labels.join(", ").length <= 24)
    return labels.join(", ")
  return `${labels[0]} +${labels.length - 1}`
}

const DAY = 24 * 60 * 60 * 1000

function datePresets(today: Date) {
  return [
    { label: "Today", from: today },
    { label: "Last 7 days", from: new Date(today.getTime() - 6 * DAY) },
    { label: "Last 30 days", from: new Date(today.getTime() - 29 * DAY) },
  ]
}

function dateSummary(value: DateRange | undefined, today: Date) {
  if (!value?.from) return null
  const preset = datePresets(today).find(
    (entry) =>
      value.from?.toDateString() === entry.from.toDateString() &&
      value.to?.toDateString() === today.toDateString(),
  )
  return (
    preset?.label ??
    [value.from, value.to]
      .filter(Boolean)
      .map((date) =>
        date!.toLocaleDateString("en-GB", { day: "numeric", month: "short" }),
      )
      .join(" – ")
  )
}

function rangeSummary(range: Range | null, unit: string) {
  if (!range) return null
  const { min, max } = range
  if (min !== undefined && max !== undefined) return `${min}–${max} ${unit}`
  if (min !== undefined) return `Over ${min} ${unit}`
  if (max !== undefined) return `Under ${max} ${unit}`
  return null
}

/** Past this many options the list gets a search box. */
const SEARCH_FROM = 8

/**
 * The one list every select filter opens, many-value or one-value, so the two
 * cannot drift apart: same rows, the tick on the right. A short list is the
 * standard dropdown menu, so it looks like every other dropdown in the
 * product; a long one needs a search box, so it is a command list. A set
 * many-value list ends in Clear.
 */
function OptionList({
  button,
  field,
  options,
  selected,
  onSelect,
  onClear,
  closeOnSelect,
}: {
  button: React.ReactElement
  field: string
  options: FilterOption[]
  selected: string[]
  onSelect: (value: string) => void
  onClear?: () => void
  /** One-value filters close on a pick; many-value ones stay open. */
  closeOnSelect: boolean
}) {
  const [open, setOpen] = React.useState(false)
  /* Ticked ones float to the top of a long list, so they are never scrolled
     out of sight — but only when it opens, not under the pointer. */
  const [order, setOrder] = React.useState(options)

  if (options.length < SEARCH_FROM) {
    return (
      <DropdownMenu modal={false} open={open} onOpenChange={setOpen}>
        <DropdownMenuTrigger asChild>{button}</DropdownMenuTrigger>
        <DropdownMenuContent
          align="start"
          className="w-auto min-w-(--radix-dropdown-menu-trigger-width)"
        >
          {options.map((option) => (
            <DropdownMenuCheckboxItem
              checked={selected.includes(option.value)}
              key={option.value}
              onSelect={(event) => {
                /* A many-value list stays open while ticking. */
                if (!closeOnSelect) event.preventDefault()
                onSelect(option.value)
              }}
            >
              {option.label}
            </DropdownMenuCheckboxItem>
          ))}
          {onClear && selected.length ? (
            <>
              <DropdownMenuSeparator />
              <DropdownMenuItem onSelect={onClear}>Clear</DropdownMenuItem>
            </>
          ) : null}
        </DropdownMenuContent>
      </DropdownMenu>
    )
  }

  return (
    <Popover
      open={open}
      onOpenChange={(next) => {
        if (next && options.length >= SEARCH_FROM)
          setOrder([
            ...options.filter((o) => selected.includes(o.value)),
            ...options.filter((o) => !selected.includes(o.value)),
          ])
        setOpen(next)
      }}
    >
      <PopoverTrigger asChild>{button}</PopoverTrigger>
      <PopoverContent align="start" className="w-64 p-0">
        <Command>
          {options.length >= SEARCH_FROM ? (
            <CommandInput placeholder={`Search ${field.toLowerCase()}`} />
          ) : null}
          <CommandList>
            <CommandEmpty>No match</CommandEmpty>
            <CommandGroup>
              {(options.length >= SEARCH_FROM ? order : options).map(
                (option) => (
                  <CommandItem
                    className="truncate"
                    data-checked={selected.includes(option.value)}
                    key={option.value}
                    onSelect={() => {
                      onSelect(option.value)
                      if (closeOnSelect) setOpen(false)
                    }}
                    value={option.label}
                  >
                    {option.label}
                  </CommandItem>
                ),
              )}
            </CommandGroup>
          </CommandList>
          {onClear && selected.length ? (
            <div className="border-t p-1">
              <Button
                className="w-full"
                onClick={onClear}
                size="sm"
                variant="ghost"
              >
                Clear
              </Button>
            </div>
          ) : null}
        </Command>
      </PopoverContent>
    </Popover>
  )
}

/** Pick one or more values. The list stays open while ticking. */
export function SelectFilter({
  field,
  options,
  value,
  onChange,
}: {
  field: string
  options: FilterOption[]
  value: string[]
  onChange: (value: string[]) => void
}) {
  return (
    <Chip
      field={field}
      summary={manySummary(options, value)}
      onClear={() => onChange([])}
      trigger={(button) => (
        <OptionList
          button={button}
          closeOnSelect={false}
          field={field}
          onClear={() => onChange([])}
          onSelect={(item) =>
            onChange(
              value.includes(item)
                ? value.filter((entry) => entry !== item)
                : [...value, item],
            )
          }
          options={options}
          selected={value}
        />
      )}
    />
  )
}

/** Pick exactly one value — a direction, a channel. Choosing closes it. */
export function ChoiceFilter({
  field,
  options,
  value,
  onChange,
}: {
  field: string
  options: FilterOption[]
  value: string | null
  onChange: (value: string | null) => void
}) {
  return (
    <Chip
      field={field}
      summary={options.find((option) => option.value === value)?.label ?? null}
      onClear={() => onChange(null)}
      trigger={(button) => (
        <OptionList
          button={button}
          closeOnSelect
          field={field}
          onSelect={(item) => onChange(item === value ? null : item)}
          options={options}
          selected={value ? [value] : []}
        />
      )}
    />
  )
}

/** A date range: presets first, then any range on the calendar. */
export function DateFilter({
  field,
  value,
  onChange,
  today,
}: {
  field: string
  value: DateRange | undefined
  onChange: (value: DateRange | undefined) => void
  /** What "today" is. Mock data is dated, so the demo fixes it. */
  today: Date
}) {
  return (
    <Chip
      field={field}
      summary={dateSummary(value, today)}
      onClear={() => onChange(undefined)}
      trigger={(button) => (
        <Popover>
          <PopoverTrigger asChild>{button}</PopoverTrigger>
          <PopoverContent align="start" className="w-auto">
            <div className="flex gap-2">
              <div className="flex flex-col gap-1">
                {datePresets(today).map((entry) => (
                  <Button
                    key={entry.label}
                    variant={
                      dateSummary(value, today) === entry.label
                        ? "secondary"
                        : "ghost"
                    }
                    size="sm"
                    className="justify-start"
                    onClick={() => onChange({ from: entry.from, to: today })}
                  >
                    {entry.label}
                  </Button>
                ))}
              </div>
              <Separator orientation="vertical" />
              <Calendar
                mode="range"
                selected={value}
                onSelect={onChange}
                defaultMonth={value?.from ?? today}
                disabled={{ after: today }}
              />
            </div>
          </PopoverContent>
        </Popover>
      )}
    />
  )
}

/**
 * A number between two bounds — duration, cost. The common bands are one
 * click; Min and Max take anything else, and either may be left empty.
 */
export function RangeFilter({
  field,
  unit,
  presets,
  value,
  onChange,
}: {
  field: string
  unit: string
  presets: Range[]
  value: Range | null
  onChange: (value: Range | null) => void
}) {
  const id = React.useId()
  const set = (next: Range) =>
    onChange(next.min === undefined && next.max === undefined ? null : next)
  const read = (raw: string) => (raw === "" ? undefined : Number(raw))
  const current = value ?? {}

  return (
    <Chip
      field={field}
      summary={rangeSummary(value, unit)}
      onClear={() => onChange(null)}
      trigger={(button) => (
        <Popover>
          <PopoverTrigger asChild>{button}</PopoverTrigger>
          <PopoverContent align="start" className="flex w-64 flex-col gap-3">
            <div className="flex flex-col gap-1">
              {presets.map((preset) => {
                const label = rangeSummary(preset, unit)!
                const on =
                  preset.min === value?.min && preset.max === value?.max
                return (
                  <Button
                    className="justify-start"
                    key={label}
                    onClick={() => set(preset)}
                    size="sm"
                    variant={on ? "secondary" : "ghost"}
                  >
                    {label}
                  </Button>
                )
              })}
            </div>
            <Separator />
            <div className="grid grid-cols-2 gap-2">
              {(["min", "max"] as const).map((bound) => (
                <Field key={bound}>
                  <FieldLabel htmlFor={`${id}-${bound}`}>
                    {bound === "min" ? "Min" : "Max"}
                  </FieldLabel>
                  <InputGroup>
                    <InputGroupInput
                      id={`${id}-${bound}`}
                      inputMode="numeric"
                      onChange={(event) =>
                        set({ ...current, [bound]: read(event.target.value) })
                      }
                      value={current[bound] ?? ""}
                    />
                    <InputGroupAddon align="inline-end">
                      <InputGroupText>{unit}</InputGroupText>
                    </InputGroupAddon>
                  </InputGroup>
                </Field>
              ))}
            </div>
          </PopoverContent>
        </Popover>
      )}
    />
  )
}

/**
 * A filter that is either on or off — "Scheduled only". Clicking the chip
 * turns it on; there is nothing to choose, so nothing opens.
 */
export function ToggleFilter({
  field,
  value,
  onChange,
}: {
  field: string
  value: boolean
  onChange: (value: boolean) => void
}) {
  return (
    <ButtonGroup>
      <Button onClick={() => onChange(!value)} size="xs" variant="outline">
        {value ? (
          <span className="font-semibold">{field}</span>
        ) : (
          <>
            <AddIcon />
            {field}
          </>
        )}
      </Button>
      {value ? (
        <Button
          aria-label={`Clear ${field}`}
          onClick={() => onChange(false)}
          size="icon-xs"
          variant="outline"
        >
          <ClearIcon />
        </Button>
      ) : null}
    </ButtonGroup>
  )
}

/** The filters not shown as chips. Choosing one adds its chip to the row. */
export function AddFilter({
  fields,
  onAdd,
}: {
  fields: { id: string; label: string }[]
  onAdd: (id: string) => void
}) {
  if (!fields.length) return null

  return (
    <DropdownMenu modal={false}>
      <DropdownMenuTrigger asChild>
        <Button variant="ghost" size="xs">
          <AddIcon />
          Filter
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start">
        {fields.map((field) => (
          <DropdownMenuItem key={field.id} onSelect={() => onAdd(field.id)}>
            {field.label}
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"

/*
 * The line diff from the design system's Unsaved changes topic
 * (save-bar-preview.tsx), shared because three places need it: the live
 * scenario save review (DES-203), and configuration versioning's save,
 * publish and compare (DES-202). FoldedDiff, below, is the reading version
 * for history and approval: numbered, aligned, untouched lines folded.
 */

type DiffLine = { kind: "same" | "removed" | "added"; text: string }

/** Line-level diff by longest common subsequence — prompts are short. */
export function diffLines(before: string, after: string): DiffLine[] {
  const a = before.split("\n")
  const b = after.split("\n")
  const table = Array.from({ length: a.length + 1 }, () =>
    Array<number>(b.length + 1).fill(0),
  )
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      table[i][j] =
        a[i] === b[j]
          ? table[i + 1][j + 1] + 1
          : Math.max(table[i + 1][j], table[i][j + 1])

  const out: DiffLine[] = []
  let i = 0
  let j = 0
  while (i < a.length && j < b.length) {
    if (a[i] === b[j]) {
      out.push({ kind: "same", text: a[i] })
      i++
      j++
    } else if (table[i + 1][j] >= table[i][j + 1]) {
      out.push({ kind: "removed", text: a[i++] })
    } else {
      out.push({ kind: "added", text: b[j++] })
    }
  }
  while (i < a.length) out.push({ kind: "removed", text: a[i++] })
  while (j < b.length) out.push({ kind: "added", text: b[j++] })
  return out
}

const LINE = "flex gap-2 px-3 py-1 whitespace-pre-wrap"
const REMOVED = "bg-destructive-tint text-destructive-tint-foreground"
const ADDED = "bg-success-tint text-success-tint-foreground"

/** Unchanged lines stay muted; only what changed carries colour. */
export function LineDiff({ before, after }: { before: string; after: string }) {
  return (
    <div className="overflow-hidden rounded-lg border text-xs">
      {diffLines(before, after).map((line, index) => (
        <div
          key={index}
          dir="auto"
          className={cn(
            LINE,
            line.kind === "removed" && REMOVED,
            line.kind === "added" && ADDED,
            line.kind === "same" && "text-muted-foreground",
          )}
        >
          <span aria-hidden className="w-3 shrink-0 select-none">
            {line.kind === "removed" ? "−" : line.kind === "added" ? "+" : ""}
          </span>
          <span>{line.text}</span>
        </div>
      ))}
    </div>
  )
}

/**
 * The same diff as two columns — the older text on the start side, the
 * newer on the end — for comparing two versions where there is room. A line
 * that went is tinted on its side, a line that came on the other; unchanged
 * lines sit level in both so the eye can run across.
 */
export function SideBySideDiff({
  before,
  after,
}: {
  before: string
  after: string
}) {
  const lines = diffLines(before, after)
  return (
    <div className="grid grid-cols-2 overflow-hidden rounded-lg border text-xs">
      <div className="border-e">
        {lines
          .filter((line) => line.kind !== "added")
          .map((line, index) => (
            <div
              key={index}
              dir="auto"
              className={cn(
                LINE,
                line.kind === "removed" ? REMOVED : "text-muted-foreground",
              )}
            >
              {line.text}
            </div>
          ))}
      </div>
      <div>
        {lines
          .filter((line) => line.kind !== "removed")
          .map((line, index) => (
            <div
              key={index}
              dir="auto"
              className={cn(
                LINE,
                line.kind === "added" ? ADDED : "text-muted-foreground",
              )}
            >
              {line.text}
            </div>
          ))}
      </div>
    </div>
  )
}

/** How many lines a change adds and removes — the "+2 −1" on a field. */
export function diffStat(before: string, after: string) {
  const lines = diffLines(before, after)
  return {
    added: lines.filter((line) => line.kind === "added").length,
    removed: lines.filter((line) => line.kind === "removed").length,
  }
}

/** "+2 −1", each half in its own colour, zero halves muted. */
export function DiffStat({
  added,
  removed,
}: {
  added: number
  removed: number
}) {
  return (
    <span className="flex items-center gap-2 text-xs font-medium tabular-nums">
      <span className={added ? "text-success" : "text-muted-foreground"}>
        +{added}
      </span>
      <span className={removed ? "text-destructive" : "text-muted-foreground"}>
        −{removed}
      </span>
    </span>
  )
}

type Side = { text: string; n: number; changed: boolean } | null
type Row = { changed: boolean; left: Side; right: Side }

/**
 * The diff as aligned rows: an unchanged line sits level on both sides, and
 * a run of removed lines pairs off against the run of added lines that
 * replaces it, so a split view never drifts out of line.
 */
function alignedRows(before: string, after: string): Row[] {
  const rows: Row[] = []
  let oldN = 0
  let newN = 0
  let removed: Side[] = []
  let added: Side[] = []
  const flush = () => {
    for (let i = 0; i < Math.max(removed.length, added.length); i++)
      rows.push({
        changed: true,
        left: removed[i] ?? null,
        right: added[i] ?? null,
      })
    removed = []
    added = []
  }
  for (const line of diffLines(before, after)) {
    if (line.kind === "same") {
      flush()
      oldN++
      newN++
      rows.push({
        changed: false,
        left: { text: line.text, n: oldN, changed: false },
        right: { text: line.text, n: newN, changed: false },
      })
    } else if (line.kind === "removed") {
      removed.push({ text: line.text, n: ++oldN, changed: true })
    } else {
      added.push({ text: line.text, n: ++newN, changed: true })
    }
  }
  flush()
  return rows
}

/** Unified rows: removed lines then added ones, numbered on their own side. */
function unifiedRows(before: string, after: string) {
  let oldN = 0
  let newN = 0
  return diffLines(before, after).map((line) => {
    if (line.kind !== "added") oldN++
    if (line.kind !== "removed") newN++
    return {
      changed: line.kind !== "same",
      kind: line.kind,
      text: line.text,
      n: line.kind === "removed" ? oldN : newN,
    }
  })
}

/**
 * Which rows to draw: every change and `context` lines either side of it.
 * The rest fold into one "n unchanged lines" row each, which opens in place.
 */
function fold<T extends { changed: boolean }>(rows: T[], context: number) {
  const near = rows.map((_, index) =>
    rows
      .slice(Math.max(0, index - context), index + context + 1)
      .some((row) => row.changed),
  )
  const out: ({ row: T } | { hidden: T[]; id: number })[] = []
  rows.forEach((row, index) => {
    if (near[index]) {
      out.push({ row })
      return
    }
    const last = out[out.length - 1]
    if (last && "hidden" in last) last.hidden.push(row)
    else out.push({ hidden: [row], id: index })
  })
  /* Folding one line saves nothing and costs a click: show it instead. */
  return out.flatMap((piece) =>
    "hidden" in piece && piece.hidden.length === 1
      ? [{ row: piece.hidden[0] }]
      : [piece],
  )
}

const NUMBER =
  "w-7 shrink-0 text-end text-muted-foreground/60 tabular-nums select-none"

/**
 * A field's diff for reading a version: line numbers in the gutter, only
 * what changed in colour, and the untouched stretches folded so a
 * one-line change in a forty-line prompt reads as one line, not forty.
 *
 * `split` puts the older text on the start side and the newer on the end,
 * row-aligned; `unified` stacks them, − above +. `bare` drops the frame for
 * a diff that sits inside a block with its own.
 */
export function FoldedDiff({
  before,
  after,
  layout = "unified",
  context = 1,
  bare = false,
}: {
  before: string
  after: string
  layout?: "unified" | "split"
  context?: number
  bare?: boolean
}) {
  const [opened, setOpened] = React.useState<Set<number>>(new Set())
  const open = (id: number) => setOpened((current) => new Set([...current, id]))

  const frame = cn("text-xs", !bare && "overflow-hidden rounded-lg border")

  if (layout === "split") {
    const pieces = fold(alignedRows(before, after), context)
    return (
      <div className={frame}>
        {pieces.map((piece, index) =>
          "row" in piece || opened.has(piece.id) ? (
            ("row" in piece ? [piece.row] : piece.hidden).map((row, j) => (
              <div className="grid grid-cols-2" key={`${index}-${j}`}>
                <SplitCell side={row.left} tone={REMOVED} />
                <SplitCell className="border-s" side={row.right} tone={ADDED} />
              </div>
            ))
          ) : (
            <FoldRow
              count={piece.hidden.length}
              key={index}
              onOpen={() => open(piece.id)}
            />
          ),
        )}
      </div>
    )
  }

  const pieces = fold(unifiedRows(before, after), context)
  return (
    <div className={frame}>
      {pieces.map((piece, index) =>
        "row" in piece || opened.has(piece.id) ? (
          ("row" in piece ? [piece.row] : piece.hidden).map((row, j) => (
            <div
              className={cn(
                LINE,
                "ps-0",
                row.kind === "removed" && REMOVED,
                row.kind === "added" && ADDED,
                row.kind === "same" && "text-muted-foreground",
              )}
              dir="auto"
              key={`${index}-${j}`}
            >
              <span className={NUMBER}>{row.n}</span>
              <span aria-hidden className="w-3 shrink-0 select-none">
                {row.kind === "removed" ? "−" : row.kind === "added" ? "+" : ""}
              </span>
              <span>{row.text}</span>
            </div>
          ))
        ) : (
          <FoldRow
            count={piece.hidden.length}
            key={index}
            onOpen={() => open(piece.id)}
          />
        ),
      )}
    </div>
  )
}

function SplitCell({
  side,
  tone,
  className,
}: {
  side: Side
  tone: string
  className?: string
}) {
  return (
    <div
      className={cn(
        LINE,
        "ps-0",
        side?.changed ? tone : "text-muted-foreground",
        !side && "bg-muted/40",
        className,
      )}
      dir="auto"
    >
      <span className={NUMBER}>{side?.n ?? ""}</span>
      <span>{side?.text ?? ""}</span>
    </div>
  )
}

function FoldRow({ count, onOpen }: { count: number; onOpen: () => void }) {
  return (
    <div className="flex bg-muted/40 ps-8">
      <Button onClick={onOpen} size="xs" variant="ghost">
        {count === 1 ? "1 unchanged line" : `${count} unchanged lines`}
      </Button>
    </div>
  )
}

"use client"

import { useEffect, useRef } from "react"

import { TONES, type OrbTone } from "@/components/shared/orb-tones"
import { Avatar } from "@/components/ui/avatar"

/**
 * A disc of liquid light that stands in for someone with no photo.
 *
 * Drawn by a fragment shader: a soft two-blob gradient seen through a lattice
 * of diamond lenses, each one flipping the light behind it, with a bevel and a
 * groove between cells. The blobs drift, so the light rolls through the
 * lattice. The name sets the tone and where
 * the blobs start, so the same name always gets the same orb and a list of
 * them does not repeat one picture.
 *
 * One WebGL context for every avatar on the page. Browsers cap live contexts
 * at around sixteen, so a context per avatar breaks a list of forty. Instead
 * a single offscreen canvas draws each visible avatar in turn, every frame,
 * at that avatar's own pixel size, and copies the frame into the avatar's 2D
 * canvas. Off-screen avatars are skipped, and under reduced motion each one
 * is drawn once and left still.
 *
 * The colours are read from the live tokens, not written here, so the orbs
 * follow a brand or whitelabel change.
 */

type Rgb = [number, number, number]

/* How far toward white the body and the light sit, for a one-token tone. */
const BODY = 0.4
const LIGHT = 0.75

function toward(rgb: Rgb, amount: number): Rgb {
  return rgb.map((c) => c + (1 - c) * amount) as Rgb
}

function toneRgb(tone: OrbTone): Rgb[] {
  const stops: readonly string[] = TONES[tone]
  const [deep, body, light] = stops.map(classRgb)
  return [deep, body ?? toward(deep, BODY), light ?? toward(deep, LIGHT)]
}

const VERTEX = `
attribute vec2 p;
void main() { gl_Position = vec4(p, 0.0, 1.0); }
`

const FRAGMENT = `
precision highp float;
uniform vec2 uRes;
uniform float uSeed;
uniform float uTime;
uniform vec3 uA;
uniform vec3 uB;
uniform vec3 uC;

/* How many cells run across the disc: fine enough to read as a texture, and
   still about five device pixels a cell on a 24px avatar. */
const float CELLS = 9.0;

/* How strongly each cell flips and magnifies the light behind it. */
const float LENS = 0.6;

/* The light: one bright blob and one deep one, drifting on their own slow
   orbits. The seed sets where each starts, so every name is at a different
   point on the same loop. */
float field(vec2 p) {
  vec2 bright = vec2(cos(uSeed + uTime * 0.7), sin(uSeed * 1.3 + uTime * 0.5)) * 0.55;
  vec2 deep = vec2(cos(uSeed + 2.6 - uTime * 0.4), sin(uSeed * 0.7 + 2.6 + uTime * 0.6)) * 0.45;
  float f = 0.5
    + 0.7 * smoothstep(1.6, 0.0, length(p - bright))
    - 0.6 * smoothstep(1.2, 0.0, length(p - deep));
  return clamp(f, 0.0, 1.0);
}

vec3 ramp(float f) {
  vec3 col = mix(uA, uB, smoothstep(0.0, 0.55, f));
  return mix(col, uC, smoothstep(0.45, 1.0, f));
}

void main() {
  vec2 uv = (gl_FragCoord.xy * 2.0 - uRes) / uRes.y;
  float mask = 1.0 - smoothstep(1.0 - 4.0 / uRes.y, 1.0, length(uv));
  if (mask <= 0.0) {
    gl_FragColor = vec4(0.0);
    return;
  }

  /* A square grid turned 45 degrees, so the cells are diamonds and the
     lines between them run on the diagonals. */
  mat2 turn = mat2(0.7071, -0.7071, 0.7071, 0.7071);
  mat2 back = mat2(0.7071, 0.7071, -0.7071, 0.7071);
  vec2 g = turn * uv * CELLS * 0.5;
  vec2 cell = fract(g) - 0.5;

  /* Each cell is a lens: it shows the light behind its own centre, flipped
     and magnified, which is what makes the lattice read as liquid glass
     rather than a pattern printed on top. */
  vec2 offset = back * cell * (2.0 / CELLS);
  float f = field(uv - offset * (1.0 + LENS));
  vec3 col = ramp(f);

  /* The bevel: each diamond catches light on its upper-left faces and falls
     into shade on the lower-right, strongest at the rim. */
  float d = max(abs(cell.x), abs(cell.y));
  vec2 face = back * (abs(cell.x) > abs(cell.y) ? vec2(sign(cell.x), 0.0) : vec2(0.0, sign(cell.y)));
  float lit = dot(face, vec2(-0.7071, 0.7071));
  col += smoothstep(0.2, 0.5, d) * lit * 0.08;

  /* The groove between cells, drawn a step deeper on the ramp than the
     light it runs through, so it shows on the pale side and sinks on the
     deep side the way a real channel would. */
  float aa = 1.5 * CELLS / uRes.y;
  float groove = smoothstep(0.5 - 2.5 * aa, 0.5, d);
  col = mix(col, ramp(f * 0.7), groove * 0.55);

  gl_FragColor = vec4(col * mask, mask);
}
`

type Renderer = {
  gl: WebGLRenderingContext
  uniforms: Record<
    "res" | "seed" | "time" | "a" | "b" | "c",
    WebGLUniformLocation | null
  >
}

let renderer: Renderer | null | undefined

function compile(gl: WebGLRenderingContext, type: number, source: string) {
  const shader = gl.createShader(type)
  if (!shader) return null
  gl.shaderSource(shader, source)
  gl.compileShader(shader)
  return gl.getShaderParameter(shader, gl.COMPILE_STATUS) ? shader : null
}

function getRenderer(): Renderer | null {
  if (renderer !== undefined) return renderer
  renderer = null

  const gl = document.createElement("canvas").getContext("webgl", {
    premultipliedAlpha: true,
  })
  if (!gl) return null

  const vertex = compile(gl, gl.VERTEX_SHADER, VERTEX)
  const fragment = compile(gl, gl.FRAGMENT_SHADER, FRAGMENT)
  const program = gl.createProgram()
  if (!vertex || !fragment || !program) return null
  gl.attachShader(program, vertex)
  gl.attachShader(program, fragment)
  gl.linkProgram(program)
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) return null
  gl.useProgram(program)

  /* One triangle that covers the whole viewport. */
  gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer())
  gl.bufferData(
    gl.ARRAY_BUFFER,
    new Float32Array([-1, -1, 3, -1, -1, 3]),
    gl.STATIC_DRAW,
  )
  const position = gl.getAttribLocation(program, "p")
  gl.enableVertexAttribArray(position)
  gl.vertexAttribPointer(position, 2, gl.FLOAT, false, 0, 0)

  renderer = {
    gl,
    uniforms: {
      res: gl.getUniformLocation(program, "uRes"),
      seed: gl.getUniformLocation(program, "uSeed"),
      time: gl.getUniformLocation(program, "uTime"),
      a: gl.getUniformLocation(program, "uA"),
      b: gl.getUniformLocation(program, "uB"),
      c: gl.getUniformLocation(program, "uC"),
    },
  }
  return renderer
}

/* A colour class as 0–1 RGB. A hidden element wearing the class gives the
   resolved colour, which may be oklch or lab, and a 2D canvas turns any CSS
   colour into sRGB pixels. */
let probe: CanvasRenderingContext2D | null = null

function classRgb(className: string): Rgb {
  probe ??= document
    .createElement("canvas")
    .getContext("2d", { willReadFrequently: true })
  if (!probe) return [0.5, 0.5, 0.5]

  const swatch = document.createElement("span")
  swatch.className = `${className} hidden`
  document.body.append(swatch)
  const value = getComputedStyle(swatch).backgroundColor
  swatch.remove()

  probe.clearRect(0, 0, 1, 1)
  probe.fillStyle = value
  probe.fillRect(0, 0, 1, 1)
  const [r, g, b] = probe.getImageData(0, 0, 1, 1).data
  return [r / 255, g / 255, b / 255]
}

function hash(value: string) {
  let h = 2166136261
  for (const char of value)
    h = Math.imul(h ^ char.charCodeAt(0), 16777619) >>> 0
  return h
}

type Orb = {
  canvas: HTMLCanvasElement
  context: CanvasRenderingContext2D
  seed: number
  colours: [number, number, number][]
  visible: boolean
}

const orbs = new Set<Orb>()
let frame = 0
const start = typeof performance === "undefined" ? 0 : performance.now()

/* Seconds of drift per real second. Slow: an avatar sits beside text someone
   is reading, and it should never pull the eye off it. */
const SPEED = 0.35

function paint(orb: Orb, time: number) {
  const r = getRenderer()
  if (!r) return
  const { gl, uniforms } = r
  const { width, height } = orb.canvas
  if (!width || !height) return

  const glCanvas = gl.canvas as HTMLCanvasElement
  if (glCanvas.width < width || glCanvas.height < height) {
    glCanvas.width = Math.max(glCanvas.width, width)
    glCanvas.height = Math.max(glCanvas.height, height)
  }

  gl.viewport(0, 0, width, height)
  gl.clearColor(0, 0, 0, 0)
  gl.clear(gl.COLOR_BUFFER_BIT)
  gl.uniform2f(uniforms.res, width, height)
  gl.uniform1f(uniforms.seed, orb.seed)
  gl.uniform1f(uniforms.time, time)
  gl.uniform3fv(uniforms.a, orb.colours[0])
  gl.uniform3fv(uniforms.b, orb.colours[1])
  gl.uniform3fv(uniforms.c, orb.colours[2])
  gl.drawArrays(gl.TRIANGLES, 0, 3)

  /* The viewport sits at the bottom of the GL canvas, which may be taller
     than this avatar, so copy from that corner. */
  orb.context.clearRect(0, 0, width, height)
  orb.context.drawImage(
    glCanvas,
    0,
    glCanvas.height - height,
    width,
    height,
    0,
    0,
    width,
    height,
  )
}

function tick(now: number) {
  const time = ((now - start) / 1000) * SPEED
  for (const orb of orbs) if (orb.visible) paint(orb, time)
  frame = orbs.size ? requestAnimationFrame(tick) : 0
}

export type OrbAvatarProps = React.ComponentProps<typeof Avatar> & {
  /** Who it stands for. Read out to screen readers and used as the seed. */
  name: string
  tone?: OrbTone
}

export function OrbAvatar({
  name,
  tone = "violet",
  children,
  ...props
}: OrbAvatarProps) {
  const ref = useRef<HTMLCanvasElement>(null)

  useEffect(() => {
    const canvas = ref.current
    const context = canvas?.getContext("2d")
    if (!canvas || !context) return

    /* Drawn at the avatar's real size in device pixels — no bigger, so a
       24px avatar costs a 48px draw on a retina screen. */
    const ratio = window.devicePixelRatio || 1
    canvas.width = Math.round(canvas.clientWidth * ratio)
    canvas.height = Math.round(canvas.clientHeight * ratio)

    const h = hash(name)
    const orb: Orb = {
      canvas,
      context,
      seed: ((h >>> 4) % 997) / 7,
      colours: toneRgb(tone),
      visible: true,
    }

    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      paint(orb, 0)
      return
    }

    const observer = new IntersectionObserver(([entry]) => {
      orb.visible = entry.isIntersecting
    })
    observer.observe(canvas)

    orbs.add(orb)
    frame ||= requestAnimationFrame(tick)

    return () => {
      observer.disconnect()
      orbs.delete(orb)
      if (!orbs.size) {
        cancelAnimationFrame(frame)
        frame = 0
      }
    }
  }, [name, tone])

  return (
    <Avatar {...props}>
      <canvas
        aria-label={name}
        className="size-full rounded-full"
        ref={ref}
        role="img"
      />
      {/* An AvatarBadge, as on any shadcn avatar. */}
      {children}
    </Avatar>
  )
}

